	const int32_t packet_ids[] = {1, 3, 2, -4};

	/* The server does not reconcile previously counted losses when
	 * out-of-order packets arrive.
	 * For {1, 3, 2, -4}:
	 * - Pkt 1: last_id=1, lost=0
	 * - Pkt 3: lost += (3-1-1)=1. lost=1. last_id=3.
	 * - Pkt 2: outorder=1. lost=1.
	 * - FIN (-4): lost += (4-3-1)=0. lost=1.
	 */
	verify_udp_packet_sequence(packet_ids, ARRAY_SIZE(packet_ids), 1, 1, 4);
